CREATE DATABASE IF NOT EXISTS nicoedu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nicoedu;
CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','admin') NOT NULL DEFAULT 'student', profile_image VARCHAR(500), education_level VARCHAR(100), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(email), INDEX(username));
CREATE TABLE subjects (subject_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, INDEX(user_id));
CREATE TABLE topics (topic_id INT AUTO_INCREMENT PRIMARY KEY, subject_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, completion_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE CASCADE, INDEX(subject_id));
CREATE TABLE notes (note_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NULL, topic_id INT NULL, title VARCHAR(255) NOT NULL, content LONGTEXT NOT NULL, tags VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE SET NULL, FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE SET NULL, INDEX(user_id), FULLTEXT(title,content));
CREATE TABLE quizzes (quiz_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NULL, topic_id INT NULL, title VARCHAR(255) NOT NULL, difficulty ENUM('easy','medium','hard') DEFAULT 'medium', total_questions INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE SET NULL, FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE SET NULL, INDEX(user_id));
CREATE TABLE quiz_questions (question_id INT AUTO_INCREMENT PRIMARY KEY, quiz_id INT NOT NULL, question_text TEXT NOT NULL, question_type ENUM('mcq','true_false','short_answer') NOT NULL DEFAULT 'mcq', option_a TEXT, option_b TEXT, option_c TEXT, option_d TEXT, correct_answer VARCHAR(10) NOT NULL, explanation TEXT, FOREIGN KEY(quiz_id) REFERENCES quizzes(quiz_id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts (attempt_id INT AUTO_INCREMENT PRIMARY KEY, quiz_id INT NOT NULL, user_id INT NOT NULL, score INT NOT NULL DEFAULT 0, percentage DECIMAL(5,2) NOT NULL DEFAULT 0, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, FOREIGN KEY(quiz_id) REFERENCES quizzes(quiz_id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, INDEX(user_id));
CREATE TABLE quiz_answers (answer_id INT AUTO_INCREMENT PRIMARY KEY, attempt_id INT NOT NULL, question_id INT NOT NULL, selected_answer VARCHAR(500), is_correct BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(attempt_id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES quiz_questions(question_id) ON DELETE CASCADE);
CREATE TABLE study_progress (progress_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NOT NULL, topic_id INT NULL, progress_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unique_progress(user_id, subject_id, topic_id), FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE CASCADE, FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE CASCADE);
CREATE TABLE study_goals (goal_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NULL, title VARCHAR(255) NOT NULL, description TEXT, target_date DATE NOT NULL, progress_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, status ENUM('active','completed','overdue') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE SET NULL, INDEX(user_id));
CREATE TABLE study_activity (activity_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, activity_type VARCHAR(60) NOT NULL, description VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, INDEX(user_id, created_at));
CREATE TABLE ai_conversations (conversation_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, INDEX(user_id));
CREATE TABLE ai_messages (message_id INT AUTO_INCREMENT PRIMARY KEY, conversation_id INT NOT NULL, sender ENUM('user','assistant') NOT NULL, message LONGTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES ai_conversations(conversation_id) ON DELETE CASCADE);
CREATE TABLE notifications (notification_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE, INDEX(user_id));
